*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    background: #f2f5f3;
    color: #1a1a1a;
    font-size: 14px;
    line-height: 1.5;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

a { color: #2e7d32; text-decoration: none; }
a:hover { text-decoration: underline; }

.agency-bar {
    background: #2e7d32;
    color: #fff;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    padding: 6px 24px;
    flex-shrink: 0;
}
.agency-bar-inner {
    max-width: 1100px;
    margin: 0 auto;
}

.topbar {
    background: #1a3c2a;
    color: #fff;
    height: 54px;
    display: flex;
    align-items: center;
    padding: 0 24px;
    flex-shrink: 0;
}
.topbar-inner {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    max-width: 1100px;
    margin: 0 auto;
}
.site-logo {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 18px;
    font-weight: 700;
    color: #fff;
    letter-spacing: 1px;
    text-decoration: none;
}
.site-logo:hover { text-decoration: none; opacity: 0.9; }
.site-logo img {
    width: 30px;
    height: 30px;
}
.site-logo-lg img {
    width: 60px;
    height: 60px;
}
.topbar-nav { display: flex; align-items: center; gap: 18px; }
.topbar-nav a { color: #8fbf9a; text-decoration: none; font-size: 14px; }
.topbar-nav a:hover { color: #fff; text-decoration: none; }
.btn-nav {
    background: rgba(255,255,255,0.12);
    padding: 6px 16px;
    border-radius: 4px;
    color: #fff !important;
    font-weight: 500;
}
.btn-nav:hover { background: rgba(255,255,255,0.2); }
.user-label { font-size: 13px; color: #8fbf9a; }

.page-nav {
    background: #fff;
    border-bottom: 1px solid #d4ddd6;
    padding: 0 24px;
    flex-shrink: 0;
}
.page-nav-inner {
    max-width: 1100px;
    margin: 0 auto;
    display: flex;
    gap: 0;
}
.page-nav a {
    padding: 12px 18px;
    font-size: 13px;
    font-weight: 500;
    color: #555;
    text-decoration: none;
    border-bottom: 2px solid transparent;
}
.page-nav a:hover { color: #1a3c2a; text-decoration: none; }
.page-nav a.active { color: #1a3c2a; border-bottom-color: #2e7d32; }

.hero {
    background: linear-gradient(135deg, #f4f7f5 0%, #e8f0ea 100%);
    padding: 56px 24px 64px;
}
.hero-centered {
    text-align: center;
    padding: 64px 24px 72px;
}
.hero-centered-inner {
    max-width: 640px;
    margin: 0 auto;
}
.hero-seal {
    width: 80px;
    height: 80px;
    margin-bottom: 20px;
}
.hero-centered .hero-kicker {
    display: inline-block;
    margin-bottom: 12px;
}
.hero-centered h1 {
    font-size: 36px;
    font-weight: 700;
    color: #1a3c2a;
    line-height: 1.15;
    margin-bottom: 16px;
}
.hero-centered p {
    font-size: 17px;
    color: #4a5568;
    line-height: 1.6;
    margin-bottom: 28px;
}
.hero-centered .hero-actions {
    display: flex;
    gap: 12px;
    justify-content: center;
}
.hero-inner {
    max-width: 1100px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    gap: 48px;
}
.hero-text { flex: 1; }
.hero-kicker {
    display: inline-block;
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    color: #2e7d32;
    margin-bottom: 12px;
    padding: 4px 12px;
    background: #e6f4ea;
    border-radius: 3px;
}
.hero-text h1 {
    font-size: 36px;
    font-weight: 700;
    color: #1a3c2a;
    line-height: 1.15;
    margin-bottom: 16px;
}
.hero-text p {
    font-size: 17px;
    color: #4a5568;
    line-height: 1.6;
    margin-bottom: 28px;
    max-width: 480px;
}
.hero-actions { display: flex; gap: 12px; }
.hero-image { flex: 0 0 380px; text-align: right; }
.hero-img {
    width: 100%;
    max-width: 380px;
    height: auto;
    border-radius: 8px;
}
.hero-image.no-img { display: none; }

.service-strip {
    background: #1a3c2a;
    padding: 0 24px;
}
.service-strip-inner {
    max-width: 1100px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0;
}
.service-strip-item {
    padding: 20px 24px;
    text-align: center;
    color: #fff;
    border-right: 1px solid rgba(255,255,255,0.08);
}
.service-strip-item:last-child { border-right: none; }
.service-strip-value {
    font-size: 22px;
    font-weight: 700;
    color: #c49a2a;
    margin-bottom: 4px;
}
.service-strip-label {
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #8fbf9a;
}

.features {
    background: #fff;
    padding: 52px 24px;
    border-top: 1px solid #d4ddd6;
}
.features-inner {
    max-width: 1100px;
    margin: 0 auto;
    display: grid;
