}
.feature-card {
    padding: 28px 24px;
    border: 1px solid #d4ddd6;
    border-radius: 6px;
    border-top: 3px solid #2e7d32;
    background: #fff;
}
.feature-card h3 {
    font-size: 16px;
    color: #1a3c2a;
    margin-bottom: 8px;
    font-weight: 600;
}
.feature-card p {
    font-size: 14px;
    color: #555;
    line-height: 1.55;
}

.notice-panel {
    background: #f4f7f5;
    padding: 48px 24px;
    border-top: 1px solid #d4ddd6;
}
.notice-panel-inner {
    max-width: 1100px;
    margin: 0 auto;
}
.notice-panel h2 {
    font-size: 18px;
    font-weight: 600;
    color: #1a3c2a;
    margin-bottom: 16px;
}
.notice-panel ul {
    list-style: none;
    padding: 0;
}
.notice-panel li {
    padding: 10px 0 10px 28px;
    position: relative;
    font-size: 14px;
    color: #4a5568;
    line-height: 1.55;
    border-bottom: 1px solid #dce5de;
}
.notice-panel li:last-child { border-bottom: none; }
